this.socketVideo.sendPrintInfo.connect(message => {
  // 接受视频信息
  if(message.indexOf('fileBase64:') > -1){
    let value = "data:video/mp4;base64," + message.substr(11)
    this.fileVideo = this.base64ToBlob(value,'fileVideo.mp4')
    this.confimSignHandler()
  }
  // 收到副摄像头设备名后，显式打开副视频流（对齐厂商 indexDouble.html「打开副视频」devChanged("subDev_:设备名")）
  if(typeof message === 'string' && message.indexOf('subDevName:') > -1 && !this.subVideoOpened){
    this.subVideoOpened = true
    var subName = message.substr(message.indexOf('subDevName:') + 11).trim()
    try {
      this.socketVideo.devChanged("subDev_:" + subName)
    } catch (e) {
      this.$notify_error('打开副视频失败：' + (e && e.message))
    }
  }
})

